-- Synthetic, transaction-local PB-014 fixture. Never run against production.
BEGIN;
CREATE FUNCTION pg_temp.assert(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION '%',message; END IF; END $$;
CREATE FUNCTION pg_temp.reject(sql text) RETURNS void LANGUAGE plpgsql AS $$ DECLARE denied boolean:=false; BEGIN BEGIN EXECUTE sql; EXCEPTION WHEN OTHERS THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Expected rejection: %',sql; END IF; END $$;
CREATE TEMP TABLE legacy AS SELECT * FROM public.feature_access_policies;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.app_settings WHERE key IN ('runner_url','runner_token')) THEN RAISE EXCEPTION 'Disposable DB must have no runner settings'; END IF; END $$;
INSERT INTO auth.users(id,email) SELECT ('c0141000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'pb014-'||n||'@example.invalid' FROM generate_series(1,3)n;
INSERT INTO public.user_roles(user_id,role,moderation_status) SELECT id,'user','active' FROM auth.users WHERE id::text LIKE 'c0141000%' ON CONFLICT(user_id) DO UPDATE SET role='user',moderation_status='active';
INSERT INTO public.beta_testers(user_id) VALUES('c0141000-0000-4000-8000-000000000001'),('c0141000-0000-4000-8000-000000000002');
UPDATE public.beta_features SET stage='beta' WHERE feature_key='ai_music_inspiration';
UPDATE public.global_ai_usage_policy SET enabled=true;
INSERT INTO public.ai_models(provider,provider_model_id,display_name,status,generator_compatible,generator_enabled,access_policy)
VALUES('openrouter','openai/gpt-6-luna','Offline PB-014 planner','enabled',true,true,'selected_users') ON CONFLICT(provider_model_id) DO UPDATE SET status='enabled',generator_enabled=true,generator_compatible=true;
INSERT INTO public.ai_models(provider,provider_model_id,display_name,status,generator_compatible,generator_enabled,access_policy) VALUES('openai','pb014-synthesis-fixture','Offline synthesis','enabled',true,true,'all_users');
INSERT INTO public.user_model_access(user_id,access_mode,allowed_models) VALUES('c0141000-0000-4000-8000-000000000001','custom',ARRAY['openai/gpt-6-luna','pb014-synthesis-fixture']) ON CONFLICT(user_id) DO UPDATE SET access_mode='custom',allowed_models=excluded.allowed_models;
SELECT pg_temp.reject($q$SELECT public.admit_music_inspiration_planner_internal('c0141000-0000-4000-8000-000000000002')$q$);
CREATE TEMP TABLE fixture(job uuid,lease uuid,planner uuid,synthesis uuid,plan jsonb,receipt jsonb);
GRANT SELECT ON fixture TO authenticated;
DO $$ DECLARE j jsonb; again jsonb; claimed public.music_inspiration_jobs; l uuid:=gen_random_uuid(); p jsonb;
BEGIN
 j:=public.start_music_inspiration_job_v3('c0141000-0000-4000-8000-000000000001',gen_random_uuid(),'{"kind":"artist","artist":"Offline PB014","depth":"standard"}','pb014-synthesis-fixture','openai','{"input":1,"output":2,"searchCreditUsd":0.008}','{"input":1,"output":2}');
 PERFORM pg_temp.assert(j->>'research_version'='2' AND j->>'planner_model'='openai/gpt-6-luna' AND j->>'planner_provider'='openrouter','Exact fixed planner identity');
 PERFORM pg_temp.assert(j->>'planner_execution_id'<>j->>'execution_id','Independent execution identities');
 again:=public.start_music_inspiration_job_v3('c0141000-0000-4000-8000-000000000001',(j->>'request_id')::uuid,j->'request','pb014-synthesis-fixture','openai','{}','{}');
 PERFORM pg_temp.assert(again=j,'Duplicate admission preserves IDs and original price snapshots');
 claimed:=public.claim_music_inspiration_job((j->>'id')::uuid,l);
 PERFORM pg_temp.assert(claimed.id IS NULL,'Old worker cannot claim two-stage job');
 claimed:=public.claim_music_inspiration_job_v2((j->>'id')::uuid,l);
 PERFORM pg_temp.assert(claimed.status='running','New worker claims');
 PERFORM pg_temp.assert((public.claim_music_inspiration_job_v2(claimed.id,gen_random_uuid())).id IS NULL,'Concurrent worker cannot claim live lease');
 p:=jsonb_build_object('version',1,'request',j->'request','entities','[]'::jsonb,'sourceLanguages','[{"code":"en","reason":"Offline fixture"}]'::jsonb,'ambiguities','[]'::jsonb,'queries','[{"text":"offline music credits arrangement","language":"en","topics":["genre_era","instruments_techniques","rhythm_tempo","harmony_melody"],"reason":"Offline"},{"text":"offline vocals structure production sources","language":"en","topics":["vocals","structure_arrangement","production_sound","sources_credits"],"reason":"Offline"}]'::jsonb);
 INSERT INTO fixture VALUES(claimed.id,l,claimed.planner_execution_id,claimed.execution_id,p,jsonb_build_object('provider','openrouter','model','openai/gpt-6-luna','text',p::text,'stopReason','end_turn','usage','{"inputTokens":100,"outputTokens":20,"totalTokens":120}'::jsonb));
END $$;
SELECT pg_temp.reject(format('SELECT public.reserve_music_inspiration_dispatch(%L,%L,%L,''search'',0,1)',job,lease,gen_random_uuid())) FROM fixture;
SELECT pg_temp.reject(format('SELECT public.checkpoint_music_inspiration_plan(%L,%L,%L::jsonb)',job,lease,plan)) FROM fixture;
SELECT pg_temp.assert(public.reserve_music_inspiration_dispatch(job,lease,planner,'planner',0,0),'Reserve planner once') FROM fixture;
SELECT pg_temp.assert(NOT public.reserve_music_inspiration_dispatch(job,lease,planner,'planner',0,0),'Duplicate planner dispatch denied') FROM fixture;
SELECT pg_temp.reject(format('SELECT public.reserve_music_inspiration_dispatch(%L,%L,%L,''planner'',0,0)',job,lease,gen_random_uuid())) FROM fixture;
SELECT public.settle_music_inspiration_dispatch(job,planner,'observed',jsonb_build_object('provider_result',receipt)) IS NOT NULL FROM fixture;
SELECT public.checkpoint_music_inspiration_plan(job,lease,plan) FROM fixture;
SELECT public.checkpoint_music_inspiration_plan(job,lease,plan) FROM fixture;
SELECT pg_temp.reject(format('SELECT public.checkpoint_music_inspiration_plan(%L,%L,%L::jsonb)',job,gen_random_uuid(),plan)) FROM fixture;
SELECT pg_temp.reject(format('SELECT public.checkpoint_music_inspiration_plan(%L,%L,%L::jsonb)',job,lease,jsonb_set(plan,'{ambiguities}','["changed plan"]'))) FROM fixture;
SELECT pg_temp.assert(public.reserve_music_inspiration_dispatch(job,lease,gen_random_uuid(),'search',0,1),'First search admitted') FROM fixture;
SELECT pg_temp.assert(public.reserve_music_inspiration_dispatch(job,lease,gen_random_uuid(),'search',0,1),'Second search admitted') FROM fixture;
SELECT pg_temp.assert(NOT public.reserve_music_inspiration_dispatch(job,lease,gen_random_uuid(),'search',0,1),'Standard search limit remains two') FROM fixture;
SELECT pg_temp.assert(public.reserve_music_inspiration_dispatch(job,lease,synthesis,'ai',0,0),'Independent synthesis reservation') FROM fixture;
SELECT pg_temp.assert(NOT public.reserve_music_inspiration_dispatch(job,lease,synthesis,'ai',0,0),'Synthesis duplicate denied') FROM fixture;
SELECT pg_temp.reject($q$DELETE FROM public.ai_models WHERE provider_model_id='openai/gpt-6-luna'$q$);
UPDATE public.music_inspiration_jobs SET status='unknown',lease_until=now()-interval '1 second' WHERE id=(SELECT job FROM fixture);
SELECT pg_temp.assert(EXISTS(SELECT 1 FROM public.pending_music_inspiration_job_ids() WHERE id=(SELECT job FROM fixture)),'Stored planner receipt is recoverable') FROM fixture;
SELECT pg_temp.assert((public.claim_music_inspiration_job_v2(job,gen_random_uuid())).status='running','Planner receipt recovery can claim safely') FROM fixture;
SELECT pg_temp.assert((public.read_music_inspiration_usage_internal('c0141000-0000-4000-8000-000000000001',job)->'planner'->'usage'->>'inputTokens')='100','Planner usage is independent and observable') FROM fixture;
SELECT pg_temp.assert(public.read_music_inspiration_usage_internal('c0141000-0000-4000-8000-000000000002',job) IS NULL,'Usage isolated by explicit owner') FROM fixture;
SELECT set_config('request.jwt.claim.sub','c0141000-0000-4000-8000-000000000002',true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert((SELECT count(*) FROM public.music_inspiration_jobs WHERE id=(SELECT job FROM fixture))=0,'RLS hides another owner job');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','c0141000-0000-4000-8000-000000000001',true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert((SELECT count(*) FROM public.music_inspiration_jobs WHERE id=(SELECT job FROM fixture))=1,'RLS retains owner access');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',true);
SELECT pg_temp.assert(NOT has_function_privilege('anon',fn,'EXECUTE') AND NOT has_function_privilege('authenticated',fn,'EXECUTE') AND has_function_privilege('service_role',fn,'EXECUTE'),'Internal RPC ACL: '||fn)
FROM (VALUES('public.admit_music_inspiration_planner_internal(uuid)'),('public.start_music_inspiration_job_v3(uuid,uuid,jsonb,text,text,jsonb,jsonb)'),('public.claim_music_inspiration_job_v2(uuid,uuid)'),('public.checkpoint_music_inspiration_plan(uuid,uuid,jsonb)')) f(fn);
UPDATE public.user_model_access SET allowed_models=ARRAY['pb014-synthesis-fixture'] WHERE user_id='c0141000-0000-4000-8000-000000000001';
SELECT pg_temp.reject(format('SELECT public.reserve_music_inspiration_dispatch(%L,%L,%L,''search'',0,1)',job,(SELECT lease_token FROM public.music_inspiration_jobs WHERE id=job),gen_random_uuid())) FROM fixture;
SELECT pg_temp.assert(NOT EXISTS((SELECT * FROM legacy EXCEPT SELECT * FROM public.feature_access_policies) UNION ALL (SELECT * FROM public.feature_access_policies EXCEPT SELECT * FROM legacy)),'All legacy feature policies unchanged');
ROLLBACK;
SELECT 'PASS: PB-014 fixed planner admission, idempotency, version fence, stages, recovery, owner RLS, permissions and legacy policies';
